 dict(id="u07-t8", titulo=T8, ideaClave="Los APPRI dan flexibilidad pero generan distorsiones (incompatibilidades, NMF expansiva, inseguridad jurídica); tras su auge hasta fines de los 90, sus beneficios ya no son evidentes y el aumento de arbitrajes incomodó a muchos gobiernos (§§ 38-39).", fuente=H),
